function contractForm(type){let clauses=type==='compra_usado'?`1. Declaração de propriedade e origem legítima.\n2. Transferência de responsabilidade após a compra.\n3. Tratamento de dados conforme LGPD.\n4. Assinatura e aceite das partes.`:`Condições de venda, garantia, estado do aparelho, IMEI, acessórios e responsabilidades.`;formModal(type==='compra_usado'?'Termo de compra de aparelho usado':'Termo de venda e garantia',`<div class="formgrid">${f('unit','Unidade','select',['LAGOS','MAGÉ'])}${f('customer_id','Cliente ID','number')}${f('device_id','Aparelho ID','number')}${f('payload','Dados e cláusulas','textarea',clauses,true)}<div class="field"><label>Assinatura do cliente</label><canvas id="sig1" class="sig"></canvas><button class="btn ghost" type="button" onclick="clearSig('sig1')">Limpar</button></div><div class="field"><label>Assinatura da loja</label><canvas id="sig2" class="sig"></canvas><button class="btn ghost" type="button" onclick="clearSig('sig2')">Limpar</button></div></div>`,async()=>{let m=$('#modal'),d=formValues(m.querySelector('#modalForm'));d.type=type;d.payload={clauses:d.payload};d.customer_signature=$('#sig1').toDataURL('image/png');d.store_signature=$('#sig2').toDataURL('image/png');await api('/api/contracts',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Termo salvo com assinaturas');render()});setTimeout(()=>{setupSig($('#sig1'));setupSig($('#sig2'))},50)}
function setupSig(c){let ctx=c.getContext('2d'),down=false;ctx.strokeStyle='#111';ctx.lineWidth=2;function pos(e){let r=c.getBoundingClientRect(),p=e.touches?.[0]||e;return{x:(p.clientX-r.left)*c.width/r.width,y:(p.clientY-r.top)*c.height/r.height}}function start(e){down=true;let p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y)}function move(e){if(!down)return;e.preventDefault();let p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke()}function end(){down=false}c.width=800;c.height=360;c.addEventListener('mousedown',start);c.addEventListener('mousemove',move);window.addEventListener('mouseup',end);c.addEventListener('touchstart',start,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',end)}function clearSig(id){let c=$('#'+id);c.getContext('2d').clearRect(0,0,c.width,c.height)}
function copyLink(t){let u=location.origin+'/public/quote/'+t;navigator.clipboard?.writeText(u);toast('Link de acompanhamento copiado')}
async function serviceDetails(id){let d=(await api('/api/services?unit=TODOS')).find(x=>x.id===id);if(!d)return;let ck=JSON.parse(d.checklist||'{}'),photos=JSON.parse(d.photos||'[]');formModal('OS #'+id,`<div class="panel"><div class="kpi"><span>Status</span><b>${badge(d.status)}</b></div><div class="kpi"><span>Valor</span><b>${money(d.price)}</b></div><div class="kpi"><span>Link</span><button class="btn ghost" onclick="navigator.clipboard.writeText(location.origin+'/public/os/${d.public_token}');toast('Link copiado')">Copiar acompanhamento</button></div><p>${esc(d.description)}</p><h3>Checklist</h3><div class="checkgrid">${Object.entries(ck).map(([k,v])=>`<div class="check"><input type="checkbox" checked disabled><label>${v?'☑':'☐'} ${esc(k)}</label></div>`).join('')}</div><h3>Fotos</h3><div class="photos">${photos.map(x=>`<img class="photo" src="${x}">`).join('')||'Sem fotos.'}</div></div>`,async()=>closeModal())}
async function unlockDetails(id){let d=(await api('/api/unlocks?unit=TODOS')).find(x=>x.id===id);if(!d)return;let ck=JSON.parse(d.checklist||'{}'),photos=JSON.parse(d.photos||'[]');formModal('Desbloqueio #'+id,`<div class="panel"><div class="kpi"><span>Status</span><b>${badge(d.status)}</b></div><div class="kpi"><span>Operação</span><b>${esc(d.kind)}</b></div><h3>Checklist</h3><div class="checkgrid">${Object.entries(ck).map(([k,v])=>`<div class="check"><input type="checkbox" checked disabled><label>${v?'☑':'☐'} ${esc(k)}</label></div>`).join('')}</div><h3>Fotos</h3><div class="photos">${photos.map(x=>`<img class="photo" src="${x}">`).join('')||'Sem fotos.'}</div></div>`,async()=>closeModal())}
function quickPhotos(table,id,photos){toast('Use a ficha da OS/aparelho para adicionar fotos no cadastro.')}
function filterCompat(){let q=($('#compat').value||'').toLowerCase();$('#compatres').textContent=q?'Pesquisa de compatibilidade: '+q+' • use os registros de películas para alimentar a base.':'Digite um modelo para localizar compatibilidades cadastradas.'}
function openSearch(){formModal('Busca global',`<div class="field"><label>Pesquisar cliente, IMEI, aparelho, OS...</label><input id="gq" class="input" autofocus><div id="gres" style="margin-top:12px"></div></div>`,async()=>closeModal());setTimeout(()=>{$('#gq').oninput=async e=>{let r=await api('/api/search?q='+encodeURIComponent(e.target.value));$('#gres').innerHTML=r.map(x=>`<div class="kpi"><span>${esc(x.source)} #${x.id}</span><b>${esc(x.value)}</b></div>`).join('')||'<span class="muted">Sem resultados.</span>'}},50)}
