/* KV CELL OS PREMIUM ULTIMATE V4 UX/SECURITY PATCH */
function formValues(form){
  if(!form || !(form instanceof HTMLFormElement)) throw new TypeError('Formulário inválido: #modalForm não é HTMLFormElement');
  const out={};
  for(const el of form.elements){
    if(!el.name || el.disabled) continue;
    if(el.type==='checkbox'){ out[el.name]=el.checked ? (el.value || '1') : ''; continue; }
    if(el.type==='radio'){ if(el.checked) out[el.name]=el.value; continue; }
    out[el.name]=el.value;
  }
  return out;
}

