pages.settings=async()=>{
  const s=await api('/api/settings'); const ai=await api('/api/ai/status');
  $('#content').innerHTML=head('Configurações','Empresa, identidade visual e integrações seguras')+`<section class="panel"><form id="sf" class="formgrid">${f('company_name','Nome da empresa', 'text', s.company_name||'KV CELL')}${f('tagline','Subtítulo','text',s.tagline||'OS PREMIUM • Laboratório avançado • Desde 2023')}${f('phone','Telefone','text',s.phone||'')}${f('instagram','Instagram','text',s.instagram||'')}${f('currency','Moeda','text',s.currency||'BRL')}${f('units','Unidades','text',s.units||'LAGOS,MAGÉ')}<div class="field full"><label>Logo da empresa</label><input id="logoInput" class="input" type="file" accept="image/png,image/jpeg,image/webp"><div id="logoPreview" class="logo-preview">${s.logo_data?`<img src="${s.logo_data}" alt="Logo">`:'Nenhuma logo cadastrada.'}</div></div><div class="field full"><button class="btn">Salvar configurações</button></div></form></section><section class="panel"><div class="panel-head"><h2>🤖 IA</h2><span class="badge ${ai.configured?'g':'r'}">${ai.configured?'CONFIGURADA':'NÃO CONFIGURADA'}</span></div><p>A chave nunca fica no frontend nem no GitHub. O backend lê <b>GEMINI_API_KEY</b> ou <b>GOOGLE_API_KEY</b> da variável de ambiente.</p><div class="kpi"><span>Modelo</span><b>${esc(ai.model)}</b></div><p class="muted">Você pode definir também GEMINI_MODEL na Square Cloud.</p></section>`;
  $('#logoInput').onchange=e=>{const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>$('#logoPreview').innerHTML=`<img src="${r.result}" alt="Logo">`;r.readAsDataURL(file)};
  $('#sf').onsubmit=async e=>{e.preventDefault();try{const d=formValues(e.target);const file=$('#logoInput').files?.[0];if(file){const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});d.logo_data=data}await api('/api/settings',{method:'POST',body:JSON.stringify(d)});toast('Configurações e logo salvas');await boot()}catch(x){toast('Não foi possível salvar: '+x.message)}};
};

